using System;using System.Data;using System.Data.OleDb;using System.Text.RegularExpressions;using System.Web.UI;using System.Web.UI.WebControls;
namespace PayrollWebApp { public class Signup:Page {
protected void Page_Load(object sender,EventArgs e){Auth.EnsureSecuritySchema();if(!IsPostBack&&Auth.IsLoggedIn()){Response.Redirect(Auth.GetLandingPage(),false);Context.ApplicationInstance.CompleteRequest();}}
private T F<T>(string id) where T:Control{return FindControl(id) as T;} private string V(string id){TextBox x=F<TextBox>(id);return x==null?"":(x.Text??"").Trim();} private OleDbParameter P(object v){return new OleDbParameter("?",v??DBNull.Value);}
protected void btnSignup_Click(object sender,EventArgs e){Label msg=F<Label>("lblMessage");try{string type=F<DropDownList>("ddlOrgType").SelectedValue,org=V("txtOrgName"),contact=V("txtContact"),mobile=V("txtMobile"),email=V("txtEmail"),address=V("txtAddress"),city=V("txtCity"),state=V("txtState"),pin=V("txtPincode"),board=F<DropDownList>("ddlBoard").SelectedValue,aff=V("txtAffiliation"),udise=V("txtUdise"),business=F<DropDownList>("ddlBusinessType").SelectedValue,gstin=V("txtGstin").ToUpperInvariant(),pan=V("txtPan").ToUpperInvariant(),username=V("txtUsername"),password=V("txtPassword"),confirm=V("txtConfirmPassword");string err=Validate(type,org,contact,mobile,email,address,city,state,pin,board,aff,udise,business,gstin,pan,username,password,confirm);if(err!=""){Show(msg,err);return;}
if(Convert.ToInt32(Db.Scalar("SELECT COUNT(*) FROM Users WHERE username=?",P(username)))>0){Show(msg,"This username is already registered.");return;}
string dupSql=type=="School"?"SELECT COUNT(*) FROM Tenants WHERE OrganizationType='School' AND (UdiseNumber=? OR AffiliationNumber=?)":"SELECT COUNT(*) FROM Tenants WHERE OrganizationType='Trading Firm' AND (GSTIN=? OR PAN=?)";object a=type=="School"?(object)udise:gstin,b=type=="School"?(object)aff:pan;if(Convert.ToInt32(Db.Scalar(dupSql,P(a),P(b)))>0){Show(msg,"A possible duplicate entity already exists. Please contact the Super User for review.");return;}
object tid=Db.Scalar(@"INSERT INTO Tenants(OrganizationName,OrganizationType,ContactPerson,Mobile,Email,AddressLine,City,StateName,Pincode,BoardType,AffiliationNumber,UdiseNumber,BusinessType,GSTIN,PAN,ApprovalStatus,CreatedOn,IsActive) OUTPUT INSERTED.TenantID VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,GETDATE(),0)",P(org),P(type),P(contact),P(mobile),P(email),P(address),P(city),P(state),P(pin),P(type=="School"?board:null),P(type=="School"?aff:null),P(type=="School"?udise:null),P(type=="Trading Firm"?business:null),P(type=="Trading Firm"?gstin:null),P(type=="Trading Firm"?pan:null),P("Pending"));int tenantId=Convert.ToInt32(tid);
object uid=Db.Scalar(@"INSERT INTO Users(username,password_hash,IsAdmin,IsActive,IsNewUser,TenantID,IsOrgAdmin) OUTPUT INSERTED.id VALUES(?,?,?,?,?,?,?)",P(username),P(Auth.HashPassword(password)),P(false),P(false),P(true),P(tenantId),P(true));int userId=Convert.ToInt32(uid);Db.Execute(@"INSERT INTO UserPermissions(UserID,DashboardView,EmployeesView,EmployeesEdit,PayrollView,PayrollProcess,LoansView,LoansEdit,ReportsView,AttendanceView,AttendanceImport) VALUES(?,?,?,?,?,?,?,?,?,?,?)",P(userId),P(true),P(true),P(true),P(true),P(true),P(true),P(true),P(true),P(true),P(true));Db.Execute("INSERT INTO OrganisationAudit(TenantID,UserID,ActionName,Details) VALUES(?,?,?,?)",P(tenantId),P(userId),P("Registration Submitted"),P(type+" - "+org));Response.Redirect("~/Login.aspx?pending=1",false);Context.ApplicationInstance.CompleteRequest();}catch(Exception ex){Show(msg,"Registration could not be completed. "+ex.Message);}}
private static string Validate(string t,string o,string c,string m,string e,string a,string city,string state,string pin,string board,string aff,string udise,string bt,string gstin,string pan,string u,string p,string cp){if(t!="School"&&t!="Trading Firm")return"Please select entity type.";if(String.IsNullOrWhiteSpace(o)||String.IsNullOrWhiteSpace(c)||String.IsNullOrWhiteSpace(m)||String.IsNullOrWhiteSpace(e)||String.IsNullOrWhiteSpace(a)||String.IsNullOrWhiteSpace(city)||String.IsNullOrWhiteSpace(state)||String.IsNullOrWhiteSpace(pin)||String.IsNullOrWhiteSpace(u)||String.IsNullOrWhiteSpace(p)||String.IsNullOrWhiteSpace(cp))return"Please complete all required fields.";if(!Regex.IsMatch(m,@"^[6-9][0-9]{9}$"))return"Enter a valid 10-digit Indian mobile number.";if(!Regex.IsMatch(e,@"^[^\s@]+@[^\s@]+\.[^\s@]+$"))return"Enter a valid email address.";if(!Regex.IsMatch(pin,@"^[1-9][0-9]{5}$"))return"Enter a valid 6-digit PIN code.";if(t=="School"&&(String.IsNullOrWhiteSpace(board)||String.IsNullOrWhiteSpace(aff)||String.IsNullOrWhiteSpace(udise)))return"Board Type, Affiliation Number and UDISE Number are required for School registration.";if(t=="Trading Firm"){if(String.IsNullOrWhiteSpace(bt)||String.IsNullOrWhiteSpace(gstin)||String.IsNullOrWhiteSpace(pan))return"Business Type, GSTIN and PAN are required.";if(!Regex.IsMatch(pan,@"^[A-Z]{5}[0-9]{4}[A-Z]$"))return"Enter a valid PAN.";if(!Regex.IsMatch(gstin,@"^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$"))return"Enter a valid GSTIN.";}if(u.Length<4||u.Length>50||!Regex.IsMatch(u,@"^[A-Za-z0-9._-]+$"))return"Username must be 4-50 characters using letters, numbers, dot, underscore or hyphen.";if(p.Length<8||!Regex.IsMatch(p,@"[A-Z]")||!Regex.IsMatch(p,@"[a-z]")||!Regex.IsMatch(p,@"[0-9]")||!Regex.IsMatch(p,@"[^A-Za-z0-9]"))return"Password must have at least 8 characters with uppercase, lowercase, number and special character.";if(p!=cp)return"Password and confirm password do not match.";return"";}
private static void Show(Label l,string t){if(l!=null)l.Text=t;}
}}
